import{_ as a,o as t,c as n,ai as o}from"./chunks/framework.jD4ETUAz.js";const u=JSON.parse('{"title":"Read Chinese annual reports with AI","description":"Read A-share annual reports with Claude and cninfo-mcp: table of contents, keyword search and page ranges, with answers in English and page references.","frontmatter":{"title":"Read Chinese annual reports with AI","description":"Read A-share annual reports with Claude and cninfo-mcp: table of contents, keyword search and page ranges, with answers in English and page references.","article":true,"date":"2026-11-16T00:00:00.000Z","editLink":false,"translation":"guides/read-annual-reports-with-ai.md","head":[["link",{"rel":"canonical","href":"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"cninfo-mcp"}],["meta",{"property":"og:title","content":"Read Chinese annual reports with AI | cninfo-mcp"}],["meta",{"property":"og:description","content":"Read A-share annual reports with Claude and cninfo-mcp: table of contents, keyword search and page ranges, with answers in English and page references."}],["meta",{"property":"og:url","content":"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai"}],["meta",{"property":"og:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Read Chinese annual reports with AI | cninfo-mcp"}],["meta",{"name":"twitter:description","content":"Read A-share annual reports with Claude and cninfo-mcp: table of contents, keyword search and page ranges, with answers in English and page references."}],["meta",{"name":"twitter:image","content":"https://youhaozhao.github.io/cninfo-mcp/og-en.png"}],["link",{"rel":"alternate","hreflang":"zh","href":"https://youhaozhao.github.io/cninfo-mcp/guides/read-annual-reports-with-ai"}],["link",{"rel":"alternate","hreflang":"en","href":"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai"}],["meta",{"property":"og:locale:alternate","content":"zh_CN"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Guides\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":3,\\"name\\":\\"Read Chinese annual reports with AI\\",\\"item\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai\\"}]},{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai#article\\",\\"headline\\":\\"Read Chinese annual reports with AI\\",\\"description\\":\\"Read A-share annual reports with Claude and cninfo-mcp: table of contents, keyword search and page ranges, with answers in English and page references.\\",\\"inLanguage\\":\\"en\\",\\"url\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai\\",\\"mainEntityOfPage\\":\\"https://youhaozhao.github.io/cninfo-mcp/en/guides/read-annual-reports-with-ai\\",\\"image\\":\\"https://youhaozhao.github.io/cninfo-mcp/og-en.png\\",\\"datePublished\\":\\"2026-11-16T00:00:00.000Z\\",\\"dateModified\\":\\"2026-11-16T07:46:57.000Z\\",\\"author\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"youhaozhao\\",\\"url\\":\\"https://github.com/youhaozhao\\"},\\"publisher\\":{\\"@type\\":\\"Person\\",\\"name\\":\\"youhaozhao\\",\\"url\\":\\"https://github.com/youhaozhao\\"},\\"isPartOf\\":{\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/#website\\"},\\"about\\":{\\"@id\\":\\"https://youhaozhao.github.io/cninfo-mcp/#software\\"}}]}"]]},"headers":[],"relativePath":"en/guides/read-annual-reports-with-ai.md","filePath":"en/guides/read-annual-reports-with-ai.md","lastUpdated":1794815217000}'),s={name:"en/guides/read-annual-reports-with-ai.md"};function r(i,e,p,h,d,l){return t(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="read-chinese-annual-reports-with-ai" tabindex="-1">Read Chinese annual reports with AI <a class="header-anchor" href="#read-chinese-annual-reports-with-ai" aria-label="Permalink to &quot;Read Chinese annual reports with AI&quot;">​</a></h1><p>Annual reports of Chinese listed companies are long, and almost all of them exist only in Chinese. cninfo-mcp lets an AI assistant read them the way an analyst would: look at the table of contents, find the relevant section, read just those pages, and answer with page references you can check. You ask in English, and the assistant reads the Chinese original.</p><p>The example below is Kweichow Moutai&#39;s 2025 annual report. The output excerpts come from real queries made in November 2026.</p><h2 id="all-you-need-to-ask" tabindex="-1">All you need to ask <a class="header-anchor" href="#all-you-need-to-ask" aria-label="Permalink to &quot;All you need to ask&quot;">​</a></h2><blockquote><p>What does Kweichow Moutai&#39;s 2025 annual report say about industry trends for the year ahead? Cite page numbers.</p></blockquote><p>The assistant does the rest: it finds the report with <code>list_reports</code>, uses <code>read_document</code> to see the table of contents and locate the section, reads those pages, and answers. There is no PDF to download or upload first.</p><h2 id="how-the-assistant-reads-a-long-report" tabindex="-1">How the assistant reads a long report <a class="header-anchor" href="#how-the-assistant-reads-a-long-report" aria-label="Permalink to &quot;How the assistant reads a long report&quot;">​</a></h2><p><code>read_document</code> has three modes, which match the three steps of reading a long filing.</p><h3 id="_1-overview-page-count-and-table-of-contents" tabindex="-1">1. Overview: page count and table of contents <a class="header-anchor" href="#_1-overview-page-count-and-table-of-contents" aria-label="Permalink to &quot;1. Overview: page count and table of contents&quot;">​</a></h3><p>With only a document URL, the tool returns the page count, the character count, the table of contents and the opening pages. An excerpt for this report:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PDF · 143 pages · 155700 characters</span></span>
<span class="line"><span>Contents:</span></span>
<span class="line"><span>第二节公司简介和主要财务指标 (p.5)</span></span>
<span class="line"><span>  七、近三年主要会计数据和财务指标 (p.6)</span></span>
<span class="line"><span>第三节管理层讨论与分析 (p.8)</span></span>
<span class="line"><span>  二、报告期内公司所处行业情况 (p.8)</span></span>
<span class="line"><span>  五、报告期内主要经营情况 (p.9)</span></span>
<span class="line"><span>  六、公司关于公司未来发展的讨论与分析 (p.21)</span></span>
<span class="line"><span>第四节公司治理、环境和社会 (p.23)</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>For a report of about 155,000 characters, the assistant starts with a map that has page numbers on it.</p><h3 id="_2-locate-keyword-search-inside-the-document" tabindex="-1">2. Locate: keyword search inside the document <a class="header-anchor" href="#_2-locate-keyword-search-inside-the-document" aria-label="Permalink to &quot;2. Locate: keyword search inside the document&quot;">​</a></h3><p>With a <code>query</code> (space-separated words, any match counts), the tool returns the pages that match, with snippets:</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;行业格局 发展趋势&quot; found on 2 page(s)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[p.8] 1 match(es)</span></span>
<span class="line"><span>[p.21] 2 match(es)</span></span></code></pre></div><p>Page 8 only points forward to the later section; page 21 is where the discussion of the industry landscape and trends begins. The assistant chooses the Chinese keywords itself and decides from the snippets which pages to read.</p><h3 id="_3-read-specific-pages" tabindex="-1">3. Read: specific pages <a class="header-anchor" href="#_3-read-specific-pages" aria-label="Permalink to &quot;3. Read: specific pages&quot;">​</a></h3><p>With <code>pages</code> (for example <code>21-23</code>), the tool returns the full text of those pages. If the text exceeds the length limit, the result ends with the page range to continue from.</p><p>Documents that have been read are cached on your machine, so steps 2 and 3 do not download or parse the file again.</p><h2 id="how-a-chinese-annual-report-is-organised" tabindex="-1">How a Chinese annual report is organised <a class="header-anchor" href="#how-a-chinese-annual-report-is-organised" aria-label="Permalink to &quot;How a Chinese annual report is organised&quot;">​</a></h2><p>A-share annual reports follow a disclosure format set by the regulator, so the same sections appear in largely the same order across companies. Knowing them helps you ask precise questions. These are the eight chapters of the example report:</p><table tabindex="0"><thead><tr><th>Chapter</th><th>Chinese title</th><th>What it contains</th></tr></thead><tbody><tr><td>1</td><td>释义</td><td>Definitions</td></tr><tr><td>2</td><td>公司简介和主要财务指标</td><td>Company profile and key financial indicators, including multi-year and quarterly figures</td></tr><tr><td>3</td><td>管理层讨论与分析</td><td>Management discussion and analysis: industry, operations, core strengths, outlook and risks</td></tr><tr><td>4</td><td>公司治理、环境和社会</td><td>Corporate governance, directors and executives, dividends, environment and social responsibility</td></tr><tr><td>5</td><td>重要事项</td><td>Significant events: commitments, related-party transactions, litigation, guarantees</td></tr><tr><td>6</td><td>股份变动及股东情况</td><td>Changes in share capital and shareholders</td></tr><tr><td>7</td><td>债券相关情况</td><td>Bonds</td></tr><tr><td>8</td><td>财务报告</td><td>The audited financial statements and notes</td></tr></tbody></table><h2 id="prompts-to-adapt" tabindex="-1">Prompts to adapt <a class="header-anchor" href="#prompts-to-adapt" aria-label="Permalink to &quot;Prompts to adapt&quot;">​</a></h2><p>Replace the company and year. Asking for page numbers makes every answer easy to verify.</p><p><strong>Management discussion</strong></p><blockquote><p>In CATL&#39;s 2025 annual report, how does management explain the change in gross margin? Quote the original and cite page numbers.</p></blockquote><p><strong>Revenue breakdown</strong></p><blockquote><p>Break down BYD&#39;s 2025 revenue and gross margin by product and by region, using the business analysis in the annual report. Cite page numbers.</p></blockquote><p><strong>Risks</strong></p><blockquote><p>What principal risks does SMIC (688981) disclose in its latest annual report, and what changed compared with the previous year?</p></blockquote><p><strong>Dividends</strong></p><blockquote><p>What is the profit distribution plan in Kweichow Moutai&#39;s 2025 annual report?</p></blockquote><p><strong>Across years</strong></p><blockquote><p>Compare the outlook sections of the 2024 and 2025 annual reports of 600519. What changed in the wording?</p></blockquote><h2 id="keeping-answers-verifiable" tabindex="-1">Keeping answers verifiable <a class="header-anchor" href="#keeping-answers-verifiable" aria-label="Permalink to &quot;Keeping answers verifiable&quot;">​</a></h2><ul><li><strong>Ask for page numbers.</strong> The assistant reads by page, so every statement can be traced to a page in the PDF.</li><li><strong>Check key figures against the filing.</strong> <code>get_financials</code> returns the condensed figures shown on CNINFO&#39;s company pages, which can differ in definition from the full statements.</li><li><strong>Watch for partial results.</strong> A result with <code>complete: false</code> is missing something, and a conclusion drawn from it is not the full picture.</li><li><strong>Scanned documents cannot be read.</strong> Some older filings have no text layer.</li><li><strong>Translations are the assistant&#39;s own.</strong> There is no official English text for most filings, so treat quoted translations as a reading aid and refer to the Chinese original for anything that matters.</li></ul><h2 id="beyond-annual-reports" tabindex="-1">Beyond annual reports <a class="header-anchor" href="#beyond-annual-reports" aria-label="Permalink to &quot;Beyond annual reports&quot;">​</a></h2><p>The same approach works for semi-annual and quarterly reports, IPO prospectuses and any announcement. Name the report type in your question, for example &quot;the 2026 semi-annual report&quot; or &quot;the IPO prospectus&quot;.</p><p>To keep local copies, see <a href="/cninfo-mcp/en/guides/download-annual-reports">Download annual reports of Chinese listed companies</a>. The parameters of <code>read_document</code> are in the <a href="/cninfo-mcp/en/reference/tools#read-document">tools reference</a>.</p>`,39)])])}const g=a(s,[["render",r]]);export{u as __pageData,g as default};
